ews are read-only; visibility is controlled here.</small></div></div><?php if(empty($reviews)):?><p class="card-muted-text">No reviews have been synchronized yet.</p><?php else:?><div class="table-wrap"><table class="data-table"><thead><tr><th>Source</th><th>Customer</th><th>Rating</th><th>Review</th><th>Date</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($reviews as $r):?><tr><td><strong><?=e(ucfirst($r['source']))?></strong></td><td><?=e($r['reviewer_name'])?></td><td><span class="review-rating-inline"><?php for($i=0;$i<(int)$r['rating'];$i++):?><i class="fa-solid fa-star"></i><?php endfor;?></span></td><td><?=e(mb_strimwidth($r['comment'],0,120,'…'))?></td><td><?=e(date('d M Y',strtotime($r['review_date'])))?></td><td><span class="badge badge-<?=$r['is_visible']?'active':'inactive'?>"><?=$r['is_visible']?'Visible':'Hidden'?></span></td><td><?php if(!empty($r['review_url'])):?><a class="btn btn-outline btn-sm" href="<?=e($r['review_url'])?>" target="_blank" rel="noopener">Open</a><?php endif;?><form action="<?=base_url('admin/reviews/'.(int)$r['id'].'/visibility')?>" method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="visible" value="<?=$r['is_visible']?'0':'1'?>"><button class="btn <?=$r['is_visible']?'btn-danger':'btn-primary'?> btn-sm"><?=$r['is_visible']?'Hide':'Show'?></button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div><div class="card"><div class="card-header"><h2>Review Request Links</h2></div><div class="review-request-links"><?php if(!empty($links['google'])):?><div><strong>Google</strong><a href="<?=e($links['google'])?>" target="_blank" rel="noopener"><?=e($links['google'])?></a></div><?php endif;?><?php if(!empty($links['tripadvisor'])):?><div><strong>Tripadvisor</strong><a href="<?=e($links['tripadvisor'])?>" target="_blank" rel="noopener"><?=e($links['tripadvisor'])?></a></div><?php endif;?><?php if(empty($links['google'])&&empty($links['tripadvisor'])):?><p class="card-muted-text">Add review URLs in Admin → Settings → Reviews.</p><?php endif;?></div></div><?php if(!empty($_SESSION['google_review_location_selected'])):$sel=$_SESSION['google_review_location_selected'];unset($_SESSION['google_review_location_selected']);?>
